package org.jlinalg.cli;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AccessDeniedException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import org.jlinalg.singlecell.MonocleResponsePreparation;
import org.jlinalg.singlecell.MonocleResponsePreparation.Transform;
import static org.jlinalg.cli.Monocle100NeighborsFiles.*;

/** Complete explicit response preparation, optional declared design assembly and portable replay. */
public final class MonocleResponsePreparationCli {
    private MonocleResponsePreparationCli() { }
    static final String PROFILE="native-monocle-response-preparation-v1";
    private static final int FILE_BYTES=67108864;
    private static final long TOTAL_INPUT_BYTES=134217728,OUTPUT_BYTES=268435456;
    private static final Pattern DECIMAL=Pattern.compile("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?");
    private static final String SCOPE="Native complete response preparation: explicit log10(expression/supplied_size_factor+0.1), or supplied expression unchanged. Optional natural log of supplied detected-gene counts and appending that column to an explicit numeric base design. No size factors, feature population, covariate coding or intercept are inferred. Preparation fits no GLM or gene test and does not establish an executed paper commit or full author pipeline. VERIFY recalculates captured arithmetic; REPLAY writes a new complete preparation and preserves its parent. No R runtime is needed.";
    private static final String ACTION="SKIP3: preparation skipped for missing or forbidden input/output access; supply permitted accessible paths. FAIL2: no complete response preparation admitted. Preserve raw inputs, logs and partials, correct the named axis, units, numeric, capacity or integrity cause and retry NEW output. Do not drop genes/cells, recompute recorded pre-filter feature metadata, estimate size factors or repair nonfinite values to force success. Require exit0, COMPLETED.json and response_preparation_admitted=true. Statistical testing is separate; read WARNINGS.md.";
    private static final Set<String> REQUIRED=Set.of("schema_version","transform","expression","input_provenance","population_declaration","out");
    private static final Set<String> OPTIONAL=Set.of("size_factors","detected_genes","detected_genes_provenance","base_design","design_provenance","maximum_operations");
    private record Matrix(List<String> genes,List<String> cells,double[][] values) { }
    private record Prepared(Matrix source,MonocleResponsePreparation.Result result,List<String> columns,double[][] base) { }
    private record Verified(Path root,Map<String,Object> parameters) { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}

    static Map<String,Object> parameters(Map<String,Object> raw) throws IOException {
        var allowed=new HashSet<>(REQUIRED);allowed.addAll(OPTIONAL);keys(raw,allowed,REQUIRED);integer(raw.get("schema_version"),1,1);
        String transform=label(raw.get("transform"));require(Set.of("size-factor-log10-plus-0.1","as-is").contains(transform),"Choose size-factor-log10-plus-0.1 or as-is explicitly");
        boolean scaled=transform.equals("size-factor-log10-plus-0.1"),detected=raw.containsKey("detected_genes"),design=raw.containsKey("base_design");
        require(raw.containsKey("size_factors")==scaled,"Supply size_factors only for the explicit size-factor/log transform");require(raw.containsKey("detected_genes_provenance")==detected,"Supplied detected-gene metadata needs explicit provenance; ignored provenance is refused");require(!design||detected,"Design assembly requires supplied detected-gene metadata");require(raw.containsKey("design_provenance")==design,"Base design requires explicit coding/intercept provenance");
        for(String name:List.of("expression","out"))label(raw.get(name));for(String name:List.of("size_factors","detected_genes","base_design"))if(raw.containsKey(name))label(raw.get(name));
        var selected=new LinkedHashMap<String,Object>();selected.put("schema_version",1);selected.put("profile",PROFILE);selected.put("transform",transform);selected.put("input_provenance",label(raw.get("input_provenance")));selected.put("population_declaration",label(raw.get("population_declaration")));selected.put("detected_genes_supplied",detected);selected.put("base_design_supplied",design);
        if(detected)selected.put("detected_genes_provenance",label(raw.get("detected_genes_provenance")));if(design)selected.put("design_provenance",label(raw.get("design_provenance")));selected.put("maximum_operations",raw.containsKey("maximum_operations")?integer(raw.get("maximum_operations"),1,2000000000):MonocleResponsePreparation.DEFAULT_MAXIMUM_OPERATIONS);return selected;
    }
    private static List<String> inputNames(Map<String,Object> parameters) {
        var names=new ArrayList<String>();names.add("expression");if(parameters.get("transform").equals("size-factor-log10-plus-0.1"))names.add("size_factors");if(Boolean.TRUE.equals(parameters.get("detected_genes_supplied")))names.add("detected_genes");if(Boolean.TRUE.equals(parameters.get("base_design_supplied")))names.add("base_design");return names;
    }
    public static int run(String[] args,PrintStream output,PrintStream error) {
        Path owned=null;boolean missingIsSkip=true;
        try {
            if(args.length==1&&args[0].equals("--help")){output.println("monocle-tools RESPONSES-1.0.0 RUN --request UTF8_JSON\nmonocle-tools RESPONSES-1.0.0 VERIFY|REPLAY --capture PATH --out NEW\nRUN requires schema_version1, transform=size-factor-log10-plus-0.1|as-is, expression TSV, input_provenance, population_declaration and NEW out. The log transform requires size_factors TSV. Optional detected_genes TSV requires detected_genes_provenance; optional base_design TSV also requires design_provenance and detected_genes. Optional maximum_operations defaults500000000. Expression header: gene_id followed by complete literal cell IDs. Per-cell table headers: cell_id/size_factor or cell_id/nFeature_RNA. Base design: cell_id followed by explicit numeric columns, including any intercept/contrasts; log_n_genes must not already exist. All cell axes must match exactly, with no reordering or subsetting. Output responses.tsv and optional design.tsv feed MORAN-LM.\nLimits:64MiB/file,128MiB input,256MiB capture,16000000 matrix entries,100000 genes,1000000 cells,128 final design columns.\n"+SCOPE+"\n"+ACTION);output.flush();return output.checkError()?2:0;}
            require(args.length>0,"Choose RUN, VERIFY or REPLAY; read --help");
            if(args[0].equals("RUN")) {
                require(args.length==3&&args[1].equals("--request"),"RUN requires only --request JSON");Path source=regular(Path.of(args[2]));var raw=read(source,1048576);var p=parameters(raw);var inputs=new LinkedHashMap<String,Path>();for(String name:inputNames(p))inputs.put(name,regular(resolve(source.getParent(),raw.get(name))));var protectedInputs=new ArrayList<>(inputs.values());protectedInputs.add(source);Path out=destination(resolve(source.getParent(),raw.get("out")),protectedInputs);Files.createDirectories(out.getParent());owned=Files.createDirectory(out);missingIsSkip=false;execute(owned,source,inputs,p,null,output);return 0;
            }
            require(args.length==5&&Set.of("VERIFY","REPLAY").contains(args[0])&&args[1].equals("--capture")&&args[3].equals("--out"),"Use exact VERIFY/REPLAY --capture PATH --out NEW");missingIsSkip=false;var parent=verify(Path.of(args[2]));Path out=destination(Path.of(args[4]).toAbsolutePath().normalize(),List.of(parent.root()));Files.createDirectories(out.getParent());owned=Files.createDirectory(out);
            if(args[0].equals("VERIFY")){write(out.resolve("WARNINGS.md"),SCOPE+"\n\n"+ACTION+"\n");json(out.resolve("RESULT.json"),Map.of("status","PASS_RECALCULATED_COMPLETE_RESPONSE_PREPARATION","profile",PROFILE,"statistical_test_executed",false));output.println("PASS complete captured response arithmetic and literal axes; read WARNINGS.md");output.flush();require(!output.checkError(),"Verification console recording failed");return 0;}
            var inputs=new LinkedHashMap<String,Path>();for(String name:inputNames(parent.parameters()))inputs.put(name,parent.root().resolve("inputs").resolve(name+".tsv"));execute(owned,parent.root().resolve("source-request.json"),inputs,parent.parameters(),parent,output);return 0;
        }catch(Exception|OutOfMemoryError failure) {
            int code=missingIsSkip&&(failure instanceof NoSuchFileException||failure instanceof AccessDeniedException)?3:2;String status=code==3?"SKIP3_RESPONSE_PREPARATION_SKIPPED":"FAIL2_NO_COMPLETE_RESPONSE_PREPARATION_ADMITTED";
            if(owned!=null)try{if(Files.exists(owned.resolve("analysis.json")))Files.move(owned.resolve("analysis.json"),owned.resolve("unadmitted-analysis.json"));json(owned.resolve("analysis.json"),Map.of("status",status,"response_preparation_admitted",false,"scientific_test_admitted",false,"cause",failure.toString()));write(owned.resolve("FAILURE.txt"),failure+"\n"+ACTION+"\n");}catch(IOException|OutOfMemoryError recording){error.println("FAIL2 failure recording incomplete: "+recording);}
            error.println(status+": "+failure+"\n"+ACTION);error.flush();return code;
        }
    }
    private static void execute(Path root,Path request,Map<String,Path> inputs,Map<String,Object> p,Verified parent,PrintStream output) throws IOException {
        write(root.resolve("WARNINGS.md"),"# Explicit response preparation\n\n"+SCOPE+"\n\n"+ACTION+"\n");json(root.resolve("analysis.json"),Map.of("status","RUNNING_NO_RESPONSE_PREPARATION_ADMITTED","response_preparation_admitted",false,"scientific_test_admitted",false));Files.createDirectory(root.resolve("inputs"));var captured=new ArrayList<Captured>();captured.add(capture(request,root.resolve("source-request.json"),1048576));long total=0;
        for(var entry:inputs.entrySet()){var file=capture(entry.getValue(),root.resolve("inputs").resolve(entry.getKey()+".tsv"),FILE_BYTES);total=Math.addExact(total,Files.size(file.copy()));require(total<=TOTAL_INPUT_BYTES,"Complete input population exceeds128MiB; no prefix is admitted");captured.add(file);}
        json(root.resolve("effective-request.json"),p);Prepared prepared=prepare(root,p);var exports=exports(prepared);for(var entry:exports.entrySet())writeBounded(root.resolve(entry.getKey()),entry.getValue());for(Captured file:captured)file.verify();
        if(parent!=null){for(var entry:exports.entrySet())require(Files.readString(parent.root().resolve(entry.getKey()),StandardCharsets.UTF_8).equals(entry.getValue()),"Complete response/design replay differs");verify(parent.root());json(root.resolve("replay.json"),Map.of("parent_preserved",true,"complete_response_design_identical",true,"parent_manifest",pin(NextflowFiles.pin(parent.root().resolve("manifest.json"),FILE_BYTES,()->{}))));}
        Files.move(root.resolve("analysis.json"),root.resolve("initial-status.json"));json(root.resolve("analysis.json"),report(prepared,p));json(root.resolve("manifest.json"),Map.of("schema_version",1,"profile",PROFILE,"files",snapshot(root,FILE_BYTES,100)));
        byte[] marker=(NextflowJson.json(Map.of("schema_version",1,"profile",PROFILE,"status","PASS_COMPLETE_NATIVE_RESPONSE_PREPARATION","response_preparation_admitted",true,"scientific_test_admitted",false))+"\n").getBytes(StandardCharsets.UTF_8);capacity(root,marker.length,1);
        output.println("PASS complete response preparation: "+prepared.result().genes()+" genes, "+prepared.result().cells()+" cells. Statistical testing is separate; read WARNINGS.md.");output.flush();require(!output.checkError(),"Console recording failed; no completed preparation admitted");for(Captured file:captured)file.verify();manifest(root);capacity(root,marker.length,1);Files.write(root.resolve("COMPLETED.json"),marker,StandardOpenOption.CREATE_NEW);
    }
    private static Verified verify(Path path) throws IOException {
        require(Files.isDirectory(path,LinkOption.NOFOLLOW_LINKS),"Complete capture directory is missing or linked");Path root=path.toRealPath();var marker=read(root.resolve("COMPLETED.json"),1048576);var markerKeys=Set.of("schema_version","profile","status","response_preparation_admitted","scientific_test_admitted");keys(marker,markerKeys,markerKeys);integer(marker.get("schema_version"),1,1);require(PROFILE.equals(marker.get("profile"))&&"PASS_COMPLETE_NATIVE_RESPONSE_PREPARATION".equals(marker.get("status"))&&Boolean.TRUE.equals(marker.get("response_preparation_admitted"))&&Boolean.FALSE.equals(marker.get("scientific_test_admitted")),"Incomplete or foreign preparation marker");manifest(root);var p=parameters(read(root.resolve("source-request.json"),1048576));require(NextflowJson.json(p).equals(NextflowJson.json(read(root.resolve("effective-request.json"),1048576))),"Source/effective response settings differ");Prepared prepared=prepare(root,p);require(NextflowJson.json(report(prepared,p)).equals(NextflowJson.json(read(root.resolve("analysis.json"),1048576))),"Saved response admission/population differs");var exports=exports(prepared);for(var entry:exports.entrySet())require(Files.readString(root.resolve(entry.getKey()),StandardCharsets.UTF_8).equals(entry.getValue()),"Complete recalculated response/design differs: "+entry.getKey());for(String name:List.of("log_n_genes.tsv","design.tsv"))require(Files.exists(root.resolve(name))==exports.containsKey(name),"Unrequested covariate/design output");manifest(root);capacity(root,0,0);return new Verified(root,p);
    }
    private static Prepared prepare(Path root,Map<String,Object> p) throws IOException {
        Path input=root.resolve("inputs");try(var files=Files.list(input)){require(files.map(path->path.getFileName().toString()).collect(java.util.stream.Collectors.toSet()).equals(inputNames(p).stream().map(name->name+".tsv").collect(java.util.stream.Collectors.toSet())),"Complete captured input population differs");}Matrix expression=expression(input.resolve("expression.tsv"));double[] factors=p.get("transform").equals("as-is")?null:column(input.resolve("size_factors.tsv"),expression.cells(),"size_factor");double[] detected=Boolean.TRUE.equals(p.get("detected_genes_supplied"))?column(input.resolve("detected_genes.tsv"),expression.cells(),"nFeature_RNA"):null;var transform=p.get("transform").equals("as-is")?Transform.AS_IS:Transform.SIZE_FACTOR_LOG10_PLUS_POINT_ONE;var result=MonocleResponsePreparation.prepare(expression.values(),factors,detected,transform,integer(p.get("maximum_operations"),1,2000000000));List<String> columns=List.of();double[][] base=null;
        if(Boolean.TRUE.equals(p.get("base_design_supplied"))){var lines=lines(input.resolve("base_design.tsv"));String[] header=fields(lines.get(0));require(header[0].equals("cell_id")&&header.length<=128,"Base design requires cell_id and at most127 explicit columns");var names=new HashSet<String>();for(String name:header)require(names.add(checkedLabel(name))&&!name.equals("log_n_genes"),"Duplicate/reserved base-design column");columns=List.copyOf(Arrays.asList(header).subList(1,header.length));require(lines.size()==expression.cells().size()+1&&(long)expression.cells().size()*(columns.size()+1)<=16000000,"Complete design population/capacity differs");base=new double[expression.cells().size()][columns.size()];for(int i=1;i<lines.size();i++){String[] row=fields(lines.get(i));require(row.length==header.length&&row[0].equals(expression.cells().get(i-1)),"Base design cell axis differs; no reorder is inferred");for(int c=1;c<row.length;c++)base[i-1][c-1]=decimal(row[c]);}}
        Prepared prepared=new Prepared(expression,result,columns,base);require(operations(prepared)<=integer(p.get("maximum_operations"),1,2000000000),"Complete response/design preparation exceeds declared operation capacity");return prepared;
    }
    private static long operations(Prepared prepared){return prepared.result().operations()+(prepared.base()==null?0:(long)prepared.result().cells()*(prepared.columns().size()+1));}
    private static Map<String,Object> report(Prepared prepared,Map<String,Object> p) {
        return Map.of("status","PASS_COMPLETE_NATIVE_RESPONSE_PREPARATION","profile",PROFILE,"response_preparation_admitted",true,"scientific_test_admitted",false,"response_units","prepared-linear-response","transform",p.get("transform"),"genes",prepared.result().genes(),"cells",prepared.result().cells(),"operations",operations(prepared),"base_design_columns",prepared.columns());
    }
    private static Map<String,String> exports(Prepared p) throws IOException {
        var files=new LinkedHashMap<String,String>();var text=new StringBuilder("gene_id");for(String cell:p.source().cells())text.append('\t').append(cell);text.append('\n');for(int gene=0;gene<p.result().genes();gene++){text.append(p.source().genes().get(gene));for(double value:p.result().response(gene))text.append('\t').append(value);text.append('\n');require(text.length()<=FILE_BYTES,"Complete response table exceeds64MiB capacity");}files.put("responses.tsv",text.toString());double[] logged=p.result().logDetectedGenes();
        if(logged!=null){text=new StringBuilder("cell_id\tlog_n_genes\n");for(int i=0;i<logged.length;i++)text.append(p.source().cells().get(i)).append('\t').append(logged[i]).append('\n');files.put("log_n_genes.tsv",text.toString());}
        if(p.base()!=null){text=new StringBuilder("cell_id");for(String name:p.columns())text.append('\t').append(name);text.append("\tlog_n_genes\n");for(int i=0;i<p.base().length;i++){text.append(p.source().cells().get(i));for(double value:p.base()[i])text.append('\t').append(value);text.append('\t').append(logged[i]).append('\n');require(text.length()<=FILE_BYTES,"Complete assembled design exceeds64MiB capacity");}files.put("design.tsv",text.toString());}return files;
    }
    private static Matrix expression(Path path) throws IOException {
        var lines=lines(path);String[] header=fields(lines.get(0));require(header.length>=2&&header[0].equals("gene_id"),"Expression requires gene_id followed by the complete cell axis");var cells=new ArrayList<String>();var seen=new HashSet<String>();for(int i=1;i<header.length;i++){String id=checkedLabel(header[i]);require(seen.add(id),"Duplicate expression cell ID");cells.add(id);}require(lines.size()>=2&&lines.size()<=100001&&cells.size()<=1000000&&(long)(lines.size()-1)*cells.size()<=16000000,"Complete expression dimensions exceed limits");var genes=new ArrayList<String>();seen.clear();double[][] values=new double[lines.size()-1][cells.size()];for(int i=1;i<lines.size();i++){String[] row=fields(lines.get(i));require(row.length==header.length,"Complete expression row width differs");String id=checkedLabel(row[0]);require(seen.add(id),"Duplicate gene ID");genes.add(id);for(int c=1;c<row.length;c++)values[i-1][c-1]=decimal(row[c]);}return new Matrix(List.copyOf(genes),List.copyOf(cells),values);
    }
    private static double[] column(Path path,List<String> cells,String name) throws IOException {var lines=lines(path);require(lines.get(0).equals("cell_id\t"+name)&&lines.size()==cells.size()+1,"Require complete cell_id/"+name+" table");double[] result=new double[cells.size()];for(int i=1;i<lines.size();i++){String[] row=fields(lines.get(i));require(row.length==2&&row[0].equals(cells.get(i-1)),"Supplied "+name+" cell axis differs; no reorder/subset is inferred");result[i-1]=decimal(row[1]);if(name.equals("nFeature_RNA")){var exact=new java.math.BigDecimal(row[1]);require(exact.compareTo(java.math.BigDecimal.ONE)>=0&&exact.compareTo(new java.math.BigDecimal("9007199254740992"))<=0&&exact.stripTrailingZeros().scale()<=0&&java.math.BigDecimal.valueOf(result[i-1]).compareTo(exact)==0,"Detected-gene metadata must be an exactly represented positive integer, not a rounded decimal");}}return result;}
    private static List<String> lines(Path path) throws IOException {String raw=NextflowFiles.utf8(NextflowFiles.bytes(regular(path),FILE_BYTES));if(raw.startsWith("\ufeff"))raw=raw.substring(1);var lines=raw.lines().toList();require(!lines.isEmpty(),"Empty input table");return lines;}
    private static String[] fields(String line) throws IOException {require(!line.isEmpty(),"Empty rows are refused, not dropped");return line.split("\t",-1);}
    private static String checkedLabel(String value) throws IOException {require(!value.isBlank()&&value.length()<=32768&&value.chars().noneMatch(c->c<32||c==127),"Require nonblank literal IDs without control characters");return value;}
    private static double decimal(String value) throws IOException {require(value.length()<=256&&DECIMAL.matcher(value).matches(),"Require finite decimal values; missing/nonfinite values are not repaired");double number=Double.parseDouble(value);require(Double.isFinite(number),"Nonfinite input value");return number;}
    private static void writeBounded(Path path,String value) throws IOException {byte[] raw=value.getBytes(StandardCharsets.UTF_8);require(raw.length<=FILE_BYTES,"Complete output exceeds64MiB verification capacity");Files.write(path,raw,StandardOpenOption.CREATE_NEW);}
    private static void manifest(Path root) throws IOException {var m=read(root.resolve("manifest.json"),67108864);keys(m,Set.of("schema_version","profile","files"),Set.of("schema_version","profile","files"));integer(m.get("schema_version"),1,1);require(PROFILE.equals(m.get("profile")),"Foreign response preparation manifest");var wanted=object(m.get("files"));var actual=snapshot(root,FILE_BYTES,100);require(wanted.keySet().equals(actual.keySet()),"Complete capture population differs");for(var row:wanted.entrySet())require(pin(row.getValue(),FILE_BYTES).equals(pin(actual.get(row.getKey()),FILE_BYTES)),"Changed complete response capture: "+row.getKey());}
    private static void capacity(Path root,long pending,int pendingFiles) throws IOException {long bytes=pending;int count=pendingFiles;try(var files=Files.walk(root)){for(Path path:files.filter(Files::isRegularFile).toList()){require(!Files.isSymbolicLink(path)&&Files.size(path)<=FILE_BYTES,"Linked/oversized capture member");bytes=Math.addExact(bytes,Files.size(path));count++;}}require(bytes<=OUTPUT_BYTES&&count<=100,"Complete capture and pending marker exceed capacity");}
}
